// Extrae del webhook de WhatsApp solo lo que el flujo necesita.
// Los avisos de estado (enviado, entregado, leído) no traen "messages" y se descartan aquí.
const salida = [];
$input.all().forEach((item, i) => {
  const v = item.json;
  const msg = (v.messages || [])[0];
  if (!msg) return;
  const contacto = (v.contacts || [])[0] || {};
  let tipo = msg.type;
  let texto = '';
  let media_id = null;
  if (tipo === 'text') {
    texto = (msg.text && msg.text.body) || '';
  } else if (tipo === 'button') {
    // Respuesta a un botón de una plantilla
    texto = (msg.button && msg.button.text) || '';
    tipo = 'text';
  } else if (tipo === 'interactive') {
    const it = msg.interactive || {};
    texto = (it.button_reply && it.button_reply.title) || (it.list_reply && it.list_reply.title) || '';
    tipo = 'text';
  } else if (tipo === 'audio') {
    media_id = (msg.audio && msg.audio.id) || null;
  }
  salida.push({
    json: {
      telefono: String(msg.from || '').replace(/\D/g, ''),
      nombre: (contacto.profile && contacto.profile.name) || '',
      message_id: msg.id,
      tipo,
      texto: String(texto).trim(),
      media_id,
      phone_number_id: (v.metadata && v.metadata.phone_number_id) || '',
    },
    pairedItem: { item: i },
  });
});
return salida;

// Meta entrega la nota de voz sin extensión; la API de transcripción
// reconoce el formato por el nombre del archivo.
const item = $input.item;
if (item.binary && item.binary.data) {
  item.binary.data.fileName = 'nota_de_voz.ogg';
  item.binary.data.fileExtension = 'ogg';
  item.binary.data.mimeType = 'audio/ogg';
}
return item;

// Junta lo que el agente necesita: el texto del cliente, los datos del negocio,
// la fecha actual y un calendario de los próximos 14 días (para que "el viernes"
// se convierta en la fecha correcta).
const cfg = $('Configuración').first().json;
const msg = $('Leer mensaje').item.json;
const contacto = $('Registrar contacto').item.json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona).setLocale('es');

// Si fue nota de voz llega la transcripción: OpenAI la deja en "text" y Gemini
// en candidates[0].content.parts. Si no, se usa el texto escrito.
const esAudio = msg.tipo === 'audio';
const transcripcion = typeof $json.text === 'string'
  ? $json.text
  : ((($json.candidates || [])[0] || {}).content || { parts: [] }).parts
    .filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join(' ');
const escrito = String((esAudio ? transcripcion : msg.texto) || '').trim();
let texto = escrito || '(mensaje sin texto)';
if (esAudio) {
  texto = escrito
    ? `[Nota de voz transcrita] ${escrito}`
    : '[El cliente envió una nota de voz que no se pudo transcribir. Pídele con amabilidad que la escriba.]';
}

const calendario = [];
for (let i = 0; i < 14; i++) {
  const d = ahora.plus({ days: i });
  const extra = i === 0 ? ' (hoy)' : i === 1 ? ' (mañana)' : '';
  calendario.push(`- ${d.toFormat('cccc')} ${d.toISODate()}${extra}`);
}

// Cuánto pasó desde el mensaje anterior ("hace 3 días"), para no retomar conversaciones viejas.
let ultimoContacto = 'este es su primer mensaje';
if (contacto.ultimo_contacto) {
  const previo = DateTime.fromJSDate(new Date(contacto.ultimo_contacto)).setZone(zona).setLocale('es');
  if (previo.isValid) ultimoContacto = previo.toRelative({ base: ahora });
}

const dias = { 1: 'lunes', 2: 'martes', 3: 'miércoles', 4: 'jueves', 5: 'viernes', 6: 'sábado', 7: 'domingo' };
const horario = typeof cfg.horario === 'string' ? JSON.parse(cfg.horario) : (cfg.horario || {});
const horarioTexto = Object.keys(dias)
  .map((k) => `${dias[k]} ${(horario[k] || []).length ? horario[k].join(' y ') : 'cerrado'}`)
  .join('; ');

return {
  json: {
    texto,
    telefono: msg.telefono,
    nombre: msg.nombre || 'cliente',
    phone_number_id: msg.phone_number_id,
    es_nuevo: contacto.es_nuevo === true,
    ultimo_contacto: ultimoContacto,
    ahora: ahora.toFormat("cccc d 'de' LLLL 'de' yyyy, h:mm a"),
    calendario: calendario.join('\n'),
    horario_texto: horarioTexto + (cfg.cerrar_festivos === false ? '' : '; festivos cerrado'),
    negocio: cfg.negocio,
    asistente: cfg.asistente,
    servicios: cfg.servicios,
    direccion: cfg.direccion,
    info_extra: cfg.info_extra,
    politica_datos_url: cfg.politica_datos_url,
    duracion_min: cfg.duracion_min,
  },
};

// Limpia los datos que envió el agente y calcula los festivos de Colombia
// (Ley 51 de 1983, "Ley Emiliani") para este año y el siguiente.
const entrada = $input.first().json;
const cfg = $('Configuración').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const hoy = DateTime.now().setZone(zona);

function pascua(anio) {
  // Algoritmo de Meeus/Jones/Butcher (calendario gregoriano)
  const a = anio % 19, b = Math.floor(anio / 100), c = anio % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const mes = Math.floor((h + l - 7 * m + 114) / 31);
  const dia = ((h + l - 7 * m + 114) % 31) + 1;
  return DateTime.fromObject({ year: anio, month: mes, day: dia }, { zone: zona });
}

function alLunes(fecha) {
  // weekday: 1 = lunes ... 7 = domingo
  return fecha.weekday === 1 ? fecha : fecha.plus({ days: 8 - fecha.weekday });
}

function festivosColombia(anio) {
  const f = (mes, dia) => DateTime.fromObject({ year: anio, month: mes, day: dia }, { zone: zona });
  const p = pascua(anio);
  return [
    f(1, 1), f(5, 1), f(7, 20), f(8, 7), f(12, 8), f(12, 25),
    alLunes(f(1, 6)), alLunes(f(3, 19)), alLunes(f(6, 29)), alLunes(f(8, 15)),
    alLunes(f(10, 12)), alLunes(f(11, 1)), alLunes(f(11, 11)),
    p.minus({ days: 3 }), p.minus({ days: 2 }),
    p.plus({ days: 43 }), p.plus({ days: 64 }), p.plus({ days: 71 }),
  ].map((d) => d.toISODate());
}

const limpiar = (v) => (v === null || v === undefined ? '' : String(v).trim());

return [{
  json: {
    accion: limpiar(entrada.accion),
    telefono: limpiar(entrada.telefono).replace(/\D/g, ''),
    nombre: limpiar(entrada.nombre) || limpiar(entrada.nombre_perfil) || 'Cliente',
    fecha: limpiar(entrada.fecha),
    hora: limpiar(entrada.hora),
    servicio: limpiar(entrada.servicio),
    notas: limpiar(entrada.notas),
    event_id: limpiar(entrada.event_id),
    festivos: cfg.cerrar_festivos === false
      ? []
      : [...festivosColombia(hoy.year), ...festivosColombia(hoy.year + 1)],
  },
  pairedItem: { item: 0 },
}];

// Valida la fecha pedida y define qué semana se lee del calendario.
const cfg = $('Configuración').first().json;
const req = $('Reglas de agenda').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona);
const diasMax = Number(cfg.dias_max) || 30;
const ultimoDia = ahora.startOf('day').plus({ days: diasMax });
const salida = (json) => [{ json, pairedItem: { item: 0 } }];

let dia = DateTime.fromISO(req.fecha, { zone: zona });
if (!/^\d{4}-\d{2}-\d{2}$/.test(req.fecha) || !dia.isValid) {
  return salida({ consultar: false, response: 'Fecha inválida. Envía la fecha en formato AAAA-MM-DD.' });
}
dia = dia.startOf('day');
let aviso = '';
if (dia < ahora.startOf('day')) {
  dia = ahora.startOf('day');
  aviso = 'La fecha pedida ya pasó; se muestran horarios desde hoy. ';
}
if (dia > ultimoDia) {
  return salida({
    consultar: false,
    response: `Solo se agenda hasta ${diasMax} días adelante (último día: ${ultimoDia.toISODate()}).`,
  });
}
const hasta = DateTime.min(dia.plus({ days: 7 }), ultimoDia.plus({ days: 1 }));
return salida({ consultar: true, aviso, desde: dia.toISO(), hasta: hasta.toISO() });

// ---- Reglas de la agenda (se leen del nodo Configuración) ----
const cfg = $('Configuración').first().json;
const req = $('Reglas de agenda').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona);
const duracion = Number(cfg.duracion_min) || 60;
const paso = Number(cfg.intervalo_min) || duracion;
const anticipacion = Number(cfg.anticipacion_min) || 0;
const diasMax = Number(cfg.dias_max) || 30;
const horario = typeof cfg.horario === 'string' ? JSON.parse(cfg.horario) : (cfg.horario || {});
const festivos = new Set(req.festivos || []);

// Rangos de atención de un día, p. ej. [[08:00, 12:00], [14:00, 18:00]]
function rangosDelDia(dia) {
  if (festivos.has(dia.toISODate())) return [];
  return (horario[String(dia.weekday)] || []).map((r) => {
    const [a, b] = r.split('-').map((s) => s.trim());
    const [ha, ma] = a.split(':').map(Number);
    const [hb, mb] = b.split(':').map(Number);
    return [
      dia.set({ hour: ha, minute: ma, second: 0, millisecond: 0 }),
      dia.set({ hour: hb, minute: mb, second: 0, millisecond: 0 }),
    ];
  });
}

// Todas las horas de inicio posibles de un día según el horario
function cuposDelDia(dia) {
  const cupos = [];
  for (const [a, b] of rangosDelDia(dia)) {
    for (let t = a; t.plus({ minutes: duracion }) <= b; t = t.plus({ minutes: paso })) cupos.push(t);
  }
  return cupos;
}

// Eventos del calendario que ocupan tiempo (ignora cancelados y los marcados como "disponible")
function bloqueos(eventos) {
  return eventos
    .filter((e) => e && e.id && e.status !== 'cancelled' && e.transparency !== 'transparent')
    .map((e) => {
      const ini = e.start && e.start.dateTime
        ? DateTime.fromISO(e.start.dateTime, { zone: zona })
        : DateTime.fromISO(e.start && e.start.date, { zone: zona });
      const fin = e.end && e.end.dateTime
        ? DateTime.fromISO(e.end.dateTime, { zone: zona })
        : DateTime.fromISO(e.end && e.end.date, { zone: zona });
      return { ini, fin, evento: e };
    })
    .filter((b) => b.ini.isValid && b.fin.isValid);
}

const choca = (inicio, b) => inicio < b.fin && inicio.plus({ minutes: duracion }) > b.ini;
const etiqueta = (d) => `${d.setLocale('es').toFormat('cccc')} ${d.toISODate()}`;
// ---- Fin de las reglas ----

// Calcula los horarios libres del día pedido y, si no hay, de los días siguientes.
// Al modelo solo le llegan horas libres: nunca nombres ni datos de otros clientes.
const rango = $('Rango de búsqueda').first().json;
const desde = DateTime.fromISO(rango.desde, { zone: zona });
const hasta = DateTime.fromISO(rango.hasta, { zone: zona });
const ocupados = bloqueos($input.all().map((it) => it.json));
const minimo = ahora.plus({ minutes: anticipacion });

const dias = [];
for (let d = desde; d < hasta; d = d.plus({ days: 1 })) {
  const libres = cuposDelDia(d).filter((t) => t >= minimo && !ocupados.some((b) => choca(t, b)));
  let motivo = 'agenda llena';
  if (festivos.has(d.toISODate())) motivo = 'festivo';
  else if (!(horario[String(d.weekday)] || []).length) motivo = 'no hay atención ese día';
  dias.push({ d, libres, motivo });
}

const lista = (ts) => ts.map((t) => t.toFormat('HH:mm')).join(', ');
const pedido = dias[0];
let texto = rango.aviso || '';
if (pedido.libres.length) {
  texto += `Horarios libres el ${etiqueta(pedido.d)}: ${lista(pedido.libres)}.`;
} else {
  texto += `El ${etiqueta(pedido.d)} no hay horarios libres (${pedido.motivo}).`;
  const otros = dias.slice(1).filter((x) => x.libres.length).slice(0, 3);
  texto += otros.length
    ? ` Próximos días con cupo: ${otros.map((x) => `${etiqueta(x.d)} (${lista(x.libres.slice(0, 6))})`).join('; ')}.`
    : ' Tampoco hay cupos en los días siguientes de esa semana.';
}
texto += ` Cada cita dura ${duracion} minutos.`;
return [{ json: { response: texto }, pairedItem: { item: 0 } }];

// ---- Reglas de la agenda (se leen del nodo Configuración) ----
const cfg = $('Configuración').first().json;
const req = $('Reglas de agenda').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona);
const duracion = Number(cfg.duracion_min) || 60;
const paso = Number(cfg.intervalo_min) || duracion;
const anticipacion = Number(cfg.anticipacion_min) || 0;
const diasMax = Number(cfg.dias_max) || 30;
const horario = typeof cfg.horario === 'string' ? JSON.parse(cfg.horario) : (cfg.horario || {});
const festivos = new Set(req.festivos || []);

// Rangos de atención de un día, p. ej. [[08:00, 12:00], [14:00, 18:00]]
function rangosDelDia(dia) {
  if (festivos.has(dia.toISODate())) return [];
  return (horario[String(dia.weekday)] || []).map((r) => {
    const [a, b] = r.split('-').map((s) => s.trim());
    const [ha, ma] = a.split(':').map(Number);
    const [hb, mb] = b.split(':').map(Number);
    return [
      dia.set({ hour: ha, minute: ma, second: 0, millisecond: 0 }),
      dia.set({ hour: hb, minute: mb, second: 0, millisecond: 0 }),
    ];
  });
}

// Todas las horas de inicio posibles de un día según el horario
function cuposDelDia(dia) {
  const cupos = [];
  for (const [a, b] of rangosDelDia(dia)) {
    for (let t = a; t.plus({ minutes: duracion }) <= b; t = t.plus({ minutes: paso })) cupos.push(t);
  }
  return cupos;
}

// Eventos del calendario que ocupan tiempo (ignora cancelados y los marcados como "disponible")
function bloqueos(eventos) {
  return eventos
    .filter((e) => e && e.id && e.status !== 'cancelled' && e.transparency !== 'transparent')
    .map((e) => {
      const ini = e.start && e.start.dateTime
        ? DateTime.fromISO(e.start.dateTime, { zone: zona })
        : DateTime.fromISO(e.start && e.start.date, { zone: zona });
      const fin = e.end && e.end.dateTime
        ? DateTime.fromISO(e.end.dateTime, { zone: zona })
        : DateTime.fromISO(e.end && e.end.date, { zone: zona });
      return { ini, fin, evento: e };
    })
    .filter((b) => b.ini.isValid && b.fin.isValid);
}

const choca = (inicio, b) => inicio < b.fin && inicio.plus({ minutes: duracion }) > b.ini;
const etiqueta = (d) => `${d.setLocale('es').toFormat('cccc')} ${d.toISODate()}`;
// ---- Fin de las reglas ----

// Revisa que la cita pedida cumpla las reglas antes de tocar el calendario.
const salida = (json) => [{ json, pairedItem: { item: 0 } }];
const error = (mensaje) => salida({ valido: false, response: mensaje });

if (!req.telefono) return error('No se identificó el número del cliente.');
if (!req.servicio) return error('Falta el servicio. Pregúntale al cliente qué servicio necesita.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(req.fecha)) return error('Fecha inválida. Usa el formato AAAA-MM-DD.');
if (!/^\d{1,2}:\d{2}$/.test(req.hora)) return error('Hora inválida. Usa el formato HH:MM de 24 horas.');

const inicio = DateTime.fromISO(`${req.fecha}T${req.hora.padStart(5, '0')}`, { zone: zona });
if (!inicio.isValid) return error('Esa fecha u hora no existe.');
if (inicio < ahora.plus({ minutes: anticipacion })) {
  return error(`Ese horario ya pasó o está muy cerca. Se agenda con mínimo ${anticipacion} minutos de anticipación.`);
}
if (inicio.startOf('day') > ahora.startOf('day').plus({ days: diasMax })) {
  return error(`Solo se agenda hasta ${diasMax} días adelante.`);
}
if (festivos.has(inicio.toISODate())) return error('Ese día es festivo y no hay atención.');
if (!cuposDelDia(inicio.startOf('day')).some((t) => +t === +inicio)) {
  return error(`Esa hora no está en la agenda. Usa consultar_disponibilidad para ver las horas válidas del ${etiqueta(inicio)}.`);
}

return salida({
  valido: true,
  inicio: inicio.toISO(),
  fin: inicio.plus({ minutes: duracion }).toISO(),
  resumen: inicio.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a"),
  telefono: req.telefono,
  nombre: req.nombre,
  servicio: req.servicio,
  notas: req.notas,
});

// Decide si la cita se puede crear: horario libre, sin duplicados
// y sin pasar el máximo de citas activas por cliente.
const cfg = $('Configuración').first().json;
const v = $('Validar cita').first().json;
const maxCitas = Number(cfg.max_citas_activas) || 3;
const salida = (json) => [{ json, pairedItem: { item: 0 } }];

const reales = (items) => items.map((it) => it.json).filter((e) => e && e.id && e.status !== 'cancelled');
const marca = `WhatsApp: ${v.telefono}`;
const delCliente = (e) => String(e.description || '').includes(marca);
const inicio = DateTime.fromISO(v.inicio);

const enEseHorario = reales($('Eventos en ese horario').all()).filter((e) => e.transparency !== 'transparent');
const propias = reales($('Citas del cliente').all()).filter(delCliente);

const repetida = enEseHorario.find(
  (e) => delCliente(e) && e.start && e.start.dateTime && +DateTime.fromISO(e.start.dateTime) === +inicio,
);
if (repetida) {
  return salida({ ok: false, response: `El cliente ya tiene esta cita agendada (${v.resumen}). ID de la cita: ${repetida.id}` });
}
if (enEseHorario.length) {
  return salida({ ok: false, response: `El horario del ${v.resumen} ya está ocupado. Consulta la disponibilidad y ofrece otra hora.` });
}
if (propias.length >= maxCitas) {
  return salida({
    ok: false,
    response: `El cliente ya tiene ${propias.length} citas próximas (máximo ${maxCitas}). Debe cancelar una antes de agendar otra.`,
  });
}

return salida({
  ok: true,
  titulo: `${v.servicio} - ${v.nombre}`,
  descripcion: [
    `Cliente: ${v.nombre}`,
    marca,
    `Servicio: ${v.servicio}`,
    v.notas ? `Notas: ${v.notas}` : null,
    'Agendada por el asistente de WhatsApp',
  ].filter(Boolean).join('\n'),
  inicio: v.inicio,
  fin: v.fin,
});

// Lista las citas futuras de quien escribe, con su ID (para cancelar o reprogramar).
const cfg = $('Configuración').first().json;
const req = $('Reglas de agenda').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona);
const marca = `WhatsApp: ${req.telefono}`;

const propias = $input.all()
  .map((it) => it.json)
  .filter((e) => e && e.id && e.status !== 'cancelled' && String(e.description || '').includes(marca))
  .map((e) => ({ e, ini: DateTime.fromISO((e.start && (e.start.dateTime || e.start.date)) || '', { zone: zona }) }))
  .filter((x) => x.ini.isValid && x.ini >= ahora)
  .sort((a, b) => a.ini - b.ini);

const texto = propias.length
  ? 'Citas próximas del cliente:\n' + propias
    .map((x, i) => `${i + 1}. ${x.ini.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a")} - ${x.e.summary || 'Cita'} (ID: ${x.e.id})`)
    .join('\n')
  : 'El cliente no tiene citas próximas.';
return [{ json: { response: texto }, pairedItem: { item: 0 } }];

// Solo se cancela una cita si tiene el número de quien escribe.
// El mensaje es el mismo si no existe o si es de otra persona, para no revelar citas ajenas.
const cfg = $('Configuración').first().json;
const req = $('Reglas de agenda').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const ahora = DateTime.now().setZone(zona);
const e = $input.first().json;
const salida = (json) => [{ json, pairedItem: { item: 0 } }];
const noEncontrada = 'No encontré una cita con ese ID a nombre de este cliente. Usa ver_mis_citas para ver sus citas.';

if (!req.event_id) return salida({ ok: false, response: 'Falta el ID de la cita. Usa ver_mis_citas para obtenerlo.' });
if (!e || e.error || !e.id || e.status === 'cancelled') return salida({ ok: false, response: noEncontrada });
if (!String(e.description || '').includes(`WhatsApp: ${req.telefono}`)) return salida({ ok: false, response: noEncontrada });

const ini = DateTime.fromISO((e.start && (e.start.dateTime || e.start.date)) || '', { zone: zona });
if (ini.isValid && ini < ahora) return salida({ ok: false, response: 'Esa cita ya pasó; no se puede cancelar.' });

return salida({
  ok: true,
  event_id: e.id,
  resumen: `${ini.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a")} - ${e.summary || 'Cita'}`,
});

// Rango del día siguiente completo, en la zona horaria del negocio.
const cfg = $('Configuración').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const manana = DateTime.now().setZone(zona).plus({ days: 1 }).startOf('day');
return [{ json: { desde: manana.toISO(), hasta: manana.plus({ days: 1 }).toISO() }, pairedItem: { item: 0 } }];

// Arma un recordatorio por cada cita de mañana que agendó el bot
// (las que tienen la línea "WhatsApp: <número>" en la descripción).
const cfg = $('Configuración').first().json;
const zona = cfg.zona_horaria || 'America/Bogota';
const salida = [];
$input.all().forEach((it, i) => {
  const e = it.json;
  if (!e || !e.id || e.status === 'cancelled' || !(e.start && e.start.dateTime)) return;
  const desc = String(e.description || '');
  const tel = (desc.match(/WhatsApp:\s*\+?(\d{8,15})/) || [])[1];
  if (!tel) return;
  const nombre = ((desc.match(/Cliente:\s*(.+)/) || [])[1] || 'cliente').trim();
  const ini = DateTime.fromISO(e.start.dateTime, { zone: zona }).setLocale('es');
  salida.push({
    json: {
      telefono: tel,
      nombre,
      fecha_texto: ini.toFormat("cccc d 'de' LLLL"),
      hora_texto: ini.toFormat('h:mm a'),
    },
    pairedItem: { item: i },
  });
});
return salida;
